import requests
u='https://www.ebi.ac.uk/europepmc/webservices/rest/search'
for q in ['uterine rupture single-layer double-layer closure Sweden cohort','TITLE:"risk of uterine rupture" AND (single-layer OR single layer) AND (double-layer OR double layer)','EXT_ID:25088680']:
 r=requests.get(u,params={'query':q,'format':'json','pageSize':10},timeout=20)
 print('\nQUERY',q,'HTTP',r.status_code)
 for x in r.json().get('resultList',{}).get('result',[]):
  print(x.get('title'),'|',x.get('pubYear'),'| PMID',x.get('pmid'),'| DOI',x.get('doi'))
  if x.get('abstractText'): print(x['abstractText'][:3000])
